#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    int split_point = n / 2;
    vector<int> first_half, second_half;

    function<void(int, int)> generate_first = [&](int i, int total) {
        if (i == split_point) {
            first_half.push_back(total);
        } else {
            generate_first(i + 1, (total + a[i]) % m);
            generate_first(i + 1, total);
        }
    };

    function<void(int, int)> generate_second = [&](int i, int total) {
        if (i == n) {
            second_half.push_back(total);
        } else {
            generate_second(i + 1, (total + a[i]) % m);
            generate_second(i + 1, total);
        }
    };

    generate_first(0, 0);
    generate_second(split_point, 0);

    sort(first_half.begin(), first_half.end());
    first_half.erase(unique(first_half.begin(), first_half.end()), first_half.end());

    int best_sum = 0;
    for (int val : second_half) {
        int position = (int)(lower_bound(first_half.begin(), first_half.end(), m - val) - first_half.begin());
        if (position > 0) {
            int candidate = first_half[position - 1] + val;
            if (candidate > best_sum) {
                best_sum = candidate;
            }
        } else {
            if (val > best_sum) {
                best_sum = val;
            }
        }
    }
    cout << best_sum << "\n";
    return 0;
}
